package com.example.expenses;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import java.math.BigDecimal;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientException;

@Component
public class ExchangeRateClient {

    @JsonIgnoreProperties(ignoreUnknown = true)
    record RateResponse(BigDecimal rate) {}

    private final RestClient client;

    public ExchangeRateClient(RestClient.Builder builder, @Value("${exchange-rate.base-url}") String baseUrl) {
        this.client = builder.baseUrl(baseUrl).build();
    }

    /** Returns EUR per one unit of the given currency. */
    public BigDecimal rateToEur(String currency) {
        try {
            RateResponse r = client.get().uri("/rates/{c}", currency).retrieve().body(RateResponse.class);
            if (r == null || r.rate() == null || r.rate().signum() <= 0) {
                throw new ExchangeRateException("Invalid rate received for " + currency, null);
            }
            return r.rate();
        } catch (RestClientException e) {
            throw new ExchangeRateException("Exchange rate unavailable for " + currency, e);
        }
    }
}
