package com.example.expenses;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

@Service
public class ClaimService {

    private final ExchangeRateClient rates;
    private final BigDecimal threshold;
    private final Map<UUID, Claim> claims = new ConcurrentHashMap<>();

    public ClaimService(ExchangeRateClient rates, @Value("${exchange-rate.threshold-eur}") BigDecimal threshold) {
        this.rates = rates;
        this.threshold = threshold;
    }

    public Claim submit(ClaimRequest req) {
        String currency = req.currency().toUpperCase();
        BigDecimal eur = "EUR".equals(currency)
                ? req.amount()
                : req.amount().multiply(rates.rateToEur(currency));
        eur = eur.setScale(2, RoundingMode.HALF_UP);
        ClaimStatus status = eur.compareTo(threshold) > 0 ? ClaimStatus.PENDING_APPROVAL : ClaimStatus.APPROVED;
        Claim claim = new Claim(UUID.randomUUID(), req.employeeId(), req.amount(), currency, eur, status);
        claims.put(claim.id(), claim);
        return claim;
    }
}
