package com.example.expenses;

import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
public class ClaimController {

    private final ClaimService service;

    public ClaimController(ClaimService service) { this.service = service; }

    @PostMapping("/claims")
    public ResponseEntity<Claim> submit(@Valid @RequestBody ClaimRequest request) {
        return ResponseEntity.status(HttpStatus.CREATED).body(service.submit(request));
    }

    @ExceptionHandler(ExchangeRateException.class)
    @ResponseStatus(HttpStatus.BAD_GATEWAY)
    public String rateFailure(ExchangeRateException e) { return e.getMessage(); }
}
